Back up the folder first, then run this on a copy until the output looks right:

```python
import sys
from datetime import datetime
from pathlib import Path

try:
    from PIL import Image
    from PIL.ExifTags import TAGS
except ImportError:
    Image = None

def shot_date(p):
    if Image:
        try:
            exif = Image.open(p)._getexif() or {}
            for k, v in exif.items():
                if TAGS.get(k) == "DateTimeOriginal":
                    return datetime.strptime(v, "%Y:%m:%d %H:%M:%S")
        except Exception:
            pass
    return datetime.fromtimestamp(p.stat().st_mtime)  # fallback

src = Path(sys.argv[1] if len(sys.argv) > 1 else ".")
exts = {".jpg", ".jpeg", ".png", ".heic"}
seen = {}

for f in sorted(p for p in src.iterdir() if p.suffix.lower() in exts):
    stamp = shot_date(f).strftime("%Y-%m-%d_%H-%M-%S")
    seen[stamp] = seen.get(stamp, 0) + 1
    n = seen[stamp]
    new = src / f"{stamp}{f'_{n}' if n > 1 else ''}{f.suffix.lower()}"
    if new == f or new.exists():
        continue
    f.rename(new)
    print(f"{f.name} -> {new.name}")
```

Two things: it falls back to file mtime when there's no EXIF, which for copies/downloads can be way off — sanity check a few. And swap `f.rename` for a print first if you want a dry run on all 3000.
